  "content": "#pragma once

#include <juce_core/juce_core.h>
#include <juce_audio_basics/juce_audio_basics.h>
#include <juce_dsp/juce_dsp.h>

namespace CogDSP
{

// TextureBodyDetector - Detect texture vs body content in audio
// Routing stage: envelope followers for transient/body detection
// Modulation source: spectral flux for tonal changes
class TextureBodyDetector
{
public:
    TextureBodyDetector() = default;
    ~TextureBodyDetector() = default;

    void prepare(double sampleRate, int samplesPerBlock);
    void process(const float* input, int numSamples);
    void reset();

    // Get smoothed texture coefficient (0-1)
    // 0 = body content, 1 = texture/transient content
    float getTextureCoefficient() const { return smoothedTextureCoeff.getTarget(); }

    // Get current path gains for routing
    // Both have minimum 5% bleed to prevent silent dead zones
    float getPathAGain() const { return pathAGain; }
    float getPathBGain() const { return pathBGain; }

    // Get spectral flux for modulation system
    float getSpectralFlux() const { return spectralFlux; }

    // Set sensitivity (0-1) - controls how responsive detector is
    void setSensitivity(float sens) { sensitivity = std::clamp(sens, 0.0f, 1.0f); }

private:
    void updateEnvelopes(const float* input, int numSamples);
    void computeSpectralFlux(const float* input, int numSamples);

    // Envelope follower state
    float fastEnvelope = 0.0f;   // 2ms attack, 80ms release
    float slowEnvelope = 0.0f;   // 80ms attack, 400ms release
    float rawTextureCoeff = 0.0f;

    // Smoothed values
    juce::SmoothedValue<float> smoothedTextureCoeff;
    float pathAGain = 0.5f;  // Texture path gain
    float pathBGain = 0.5f;  // Body path gain

    // Spectral flux for modulation
    juce::dsp::FFT fft;
    juce::AudioBuffer<float> fftBuffer;
    std::vector<float> previousMagnitude;
    float spectralFlux = 0.0f;
    int fftHopCounter = 0;
    int fftSize = 1024;

    // Parameters
    double sampleRate = 44100.0;
    float sensitivity = 0.5f;

    // Envelope time constants (calculated in prepare)
    float fastAttackCoeff = 0.0f;
    float fastReleaseCoeff = 0.0f;
    float slowAttackCoeff = 0.0f;
    float slowReleaseCoeff = 0.0f;
    float smoothingCoeff = 0.0f;
};

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/TextureBodyDetector.cpp",
  "content": "#include "TextureBodyDetector.h"
#include "FastMath.h"
#include <cmath>

namespace CogDSP
{

void TextureBodyDetector::prepare(double sr, int samplesPerBlock)
{
    sampleRate = sr;

    // Time constants for envelope followers
    // Fast: 2ms attack, 80ms release
    // Slow: 80ms attack, 400ms release
    constexpr float fastAttackMs = 2.0f;
    constexpr float fastReleaseMs = 80.0f;
    constexpr float slowAttackMs = 80.0f;
    constexpr float slowReleaseMs = 400.0f;
    constexpr float smoothingMs = 5.0f;

    // Calculate coefficients: coeff = 1 - exp(-2.2 / (time * sr/1000))
    // Using tau-based: coeff = exp(-1 / (time * sr/1000))
    const auto calcCoeff = [sr](float ms) -> float {
        return static_cast<float>(std::exp(-1.0 / (ms * sr / 1000.0)));
    };

    fastAttackCoeff = calcCoeff(fastAttackMs);
    fastReleaseCoeff = calcCoeff(fastReleaseMs);
    slowAttackCoeff = calcCoeff(slowAttackMs);
    slowReleaseCoeff = calcCoeff(slowReleaseMs);
    smoothingCoeff = calcCoeff(smoothingMs);

    // Initialize smoothed value
    smoothedTextureCoeff.reset(sampleRate);
    smoothedTextureCoeff.setCurrentAndTargetValue(0.5f);
    smoothedTextureCoeff.setRampLength(0.005);  // 5ms smoothing

    // Initialize FFT
    fft = juce::dsp::FFT(static_cast<int>(std::log2(fftSize)));
    fftBuffer.setSize(1, fftSize * 2);  // Complex needs 2x
    fftBuffer.clear();
    previousMagnitude.resize(fftSize / 2 + 1, 0.0f);
    fftHopCounter = 0;

    reset();
}

void TextureBodyDetector::process(const float* input, int numSamples)
{
    updateEnvelopes(input, numSamples);
    computeSpectralFlux(input, numSamples);
}

void TextureBodyDetector::updateEnvelopes(const float* input, int numSamples)
{
    for (int i = 0; i < numSamples; ++i)
    {
        const float x = std::abs(input[i]);

        // Fast envelope follower (2ms attack, 80ms release)
        if (x > fastEnvelope)
            fastEnvelope = fastAttackCoeff * fastEnvelope + (1.0f - fastAttackCoeff) * x;
        else
            fastEnvelope = fastReleaseCoeff * fastEnvelope + (1.0f - fastReleaseCoeff) * x;

        // Slow envelope follower (80ms attack, 400ms release)
        if (x > slowEnvelope)
            slowEnvelope = slowAttackCoeff * slowEnvelope + (1.0f - slowAttackCoeff) * x;
        else
            slowEnvelope = slowReleaseCoeff * slowEnvelope + (1.0f - slowReleaseCoeff) * x;

        // Texture coefficient = (fast - slow) normalized 0-1
        // When fast >> slow, there's transient content (texture)
        // When fast ≈ slow, there's sustained content (body)
        const float diff = fastEnvelope - slowEnvelope;
        rawTextureCoeff = std::clamp(0.5f + diff * sensitivity * 2.0f, 0.0f, 1.0f);
    }

    // Apply 5ms smoothing to prevent AM artifacts at the split point
    smoothedTextureCoeff.setTargetValue(rawTextureCoeff);
    smoothedTextureCoeff.skip(numSamples);
    const float smoothed = smoothedTextureCoeff.getCurrentValue();

    // Calculate path gains with minimum 5% bleed to prevent silent dead zones
    // pathAGain = max(0.05, smoothed)  -- texture path
    // pathBGain = max(0.05, 1 - smoothed)  -- body path
    pathAGain = std::max(0.05f, smoothed);
    pathBGain = std::max(0.05f, 1.0f - smoothed);
}

void TextureBodyDetector::computeSpectralFlux(const float* input, int numSamples)
{
    // Process FFT on hop boundaries (50% overlap)
    fftHopCounter += numSamples;

    if (fftHopCounter >= fftSize / 2)
    {
        fftHopCounter = 0;

        // Copy input to FFT buffer with Hann window
        auto* fftData = fftBuffer.getWritePointer(0);

        // Clear and copy
        std::fill(fftData, fftData + fftSize * 2, 0.0f);

        for (int i = 0; i < fftSize && i < numSamples; ++i)
        {
            // Hann window
            const float window = 0.5f * (1.0f - std::cos(2.0f * Constants::PI * i / fftSize));
            fftData[i] = input[i] * window;
        }

        // Perform FFT
        fft.performRealForward(fftData);

        // Compute spectral flux (sum of positive magnitude differences)
        float flux = 0.0f;
        const int numBins = fftSize / 2 + 1;

        for (int bin = 0; bin < numBins; ++bin)
        {
            const float re = fftData[bin * 2];
            const float im = fftData[bin * 2 + 1];
            const float mag = std::sqrt(re * re + im * im);

            // Positive difference only (onset detection)
            const float diff = mag - previousMagnitude[bin];
            if (diff > 0.0f)
                flux += diff * diff;

            previousMagnitude[bin] = mag;
        }

        // Normalize and smooth
        spectralFlux = std::sqrt(flux) / static_cast<float>(numBins);
    }
}

void TextureBodyDetector::reset()
{
    fastEnvelope = 0.0f;
    slowEnvelope = 0.0f;
    rawTextureCoeff = 0.5f;
    smoothedTextureCoeff.setCurrentAndTargetValue(0.5f);
    pathAGain = 0.5f;
    pathBGain = 0.5f;
    spectralFlux = 0.0f;
    fftHopCounter = 0;

    if (fftBuffer.getNumSamples() > 0)
        fftBuffer.clear();

    std::fill(previousMagnitude.begin(), previousMagnitude.end(), 0.0f);
}

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/Waveshaper.h",
  "content": "#pragma once

#include <juce_core/juce_core.h>
#include <juce_audio_basics/juce_audio_basics.h>
#include "FastMath.h"
#include "DCBlocker.h"
#include "DelayLine.h"

namespace CogDSP
{

// Waveshaper - Custom waveshaping for Path A (Texture/Transients)
// Two bounded curves: soft (tanh) and hard (atan)
// Crossfade between curves controlled by drive parameter
// Bypass at drive=0 for perfect transparency
// DC blocker after waveshaping
// Latency compensation delay to align with Path B
class Waveshaper
{
public:
    Waveshaper() = default;
    ~Waveshaper() = default;

    void prepare(double sampleRate, int samplesPerBlock, int latencySamples);
    void process(float* left, float* right, int numSamples);
    void reset();

    // Drive: 0-1
    // 0 = bypass (transparent)
    // 0-0.5 = soft curve (warm, even harmonics)
    // 0.5-1 = hard curve (asymmetric, aggressive)
    void setDrive(float drive) { this->drive = std::clamp(drive, 0.0f, 1.0f); }

    // Get latency compensation samples for Path B alignment
    int getLatencySamples() const { return latencySamples; }

private:
    // Process single sample through waveshaper
    float processSample(float input, float drive);

    // Soft curve: tanh(x * (1 + gain * 3))
    // Warm, even harmonics, tube-style
    float softCurve(float x, float gain);

    // Hard curve: (2/PI) * atan(x * (1 + gain * 8))
    // Asymmetric, odd+even harmonics, aggressive bite
    // Bounded to ±0.64 at all inputs
    float hardCurve(float x, float gain);

    float drive = 0.3f;
    int latencySamples = 0;
    double sampleRate = 44100.0;

    // DC blocker after waveshaping
    DCBlocker dcBlockerL, dcBlockerR;

    // Latency compensation delay (to align with spectral engine latency)
    DelayLine<float> latencyDelayL, latencyDelayR;

    // Smoothed drive value
    juce::SmoothedValue<float> smoothedDrive;
};

} // namespace CogDSP"
}

