  "file_path": "/home/myuser/CogVST/src/DSP/ResonantFilter.h",
  "content": "#pragma once

#include <juce_core/juce_core.h>
#include <juce_audio_basics/juce_audio_basics.h>
#include "FastMath.h"

namespace CogDSP
{

// ResonantFilter - Cytomic TPT State Variable Filter
// Unconditionally stable at all frequencies and resonance settings
// Supports LP, HP, BP, and Notch modes
// Auto-gain compensation: 1/sqrt(Q)
// Modulation applied in octave-space for musical response
class ResonantFilter
{
public:
    enum class Mode
    {
        LP,     // Low-pass
        HP,     // High-pass
        BP,     // Band-pass
        Notch   // Notch (band-reject)
    };

    ResonantFilter() = default;
    ~ResonantFilter() = default;

    void prepare(double sampleRate);
    void process(float* samples, int numSamples);
    void reset();

    // Cutoff: 20Hz - 20kHz (log-scaled internally)
    void setCutoff(float freqHz);

    // Resonance: 0-1 maps to Q 0.5-100
    void setResonance(float res);

    // Filter mode
    void setMode(Mode m) { mode = m; }

    // Set modulation offset in octaves (-4 to +4)
    // This is summed with base cutoff in process()
    void setModulationOctaves(float octaves) { modOctaves = std::clamp(octaves, -4.0f, 4.0f); }

    // Get auto-gain compensation factor
    float getAutoGain() const { return autoGain; }

private:
    // TPT SVF core processing
    void updateCoefficients();

    // Process single sample through all filter modes
    void processSample(float& sample);

    float cutoff = 1000.0f;     // Base cutoff in Hz
    float resonance = 0.3f;      // 0-1 maps to Q 0.5-100
    float modOctaves = 0.0f;    // Modulation in octaves
    Mode mode = Mode::LP;

    double sampleRate = 44100.0;

    // TPT coefficients
    float g = 0.0f;     // tan(π*fc/fs)
    float k = 0.0f;     // 2 - 2*g (for resonance)
    float gk = 0.0f;    // g * k
    float gk2 = 0.0f;   // g / (1 + g*k)
    float oneOverDenom = 1.0f;

    // Auto-gain compensation
    float autoGain = 1.0f;

    // State variables
    float ic1eq = 0.0f;  // Integrator 1 state
    float ic2eq = 0.0f;  // Integrator 2 state

    // Smoothed cutoff for modulation
    juce::SmoothedValue<float> smoothedCutoff;
};

// Stereo version for parallel processing
class ResonantFilterStereo
{
public:
    ResonantFilterStereo() = default;
    ~ResonantFilterStereo() = default;

    void prepare(double sampleRate)
    {
        filterL.prepare(sampleRate);
        filterR.prepare(sampleRate);
    }

    void process(float* left, float* right, int numSamples)
    {
        filterL.process(left, numSamples);
        filterR.process(right, numSamples);
    }

    void reset()
    {
        filterL.reset();
        filterR.reset();
    }

    void setCutoff(float freqHz)
    {
        filterL.setCutoff(freqHz);
        filterR.setCutoff(freqHz);
    }

    void setResonance(float res)
    {
        filterL.setResonance(res);
        filterR.setResonance(res);
    }

    void setMode(ResonantFilter::Mode m)
    {
        filterL.setMode(m);
        filterR.setMode(m);
    }

    void setModulationOctaves(float octaves)
    {
        filterL.setModulationOctaves(octaves);
        filterR.setModulationOctaves(octaves);
    }

private:
    ResonantFilter filterL, filterR;
};

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/ResonantFilter.cpp",
  "content": "#include "ResonantFilter.h"
#include <cmath>

namespace CogDSP
{

void ResonantFilter::prepare(double sr)
{
    sampleRate = sr;
    smoothedCutoff.reset(sampleRate);
    smoothedCutoff.setCurrentAndTargetValue(cutoff);
    smoothedCutoff.setRampLength(0.01);  // 10ms for cutoff changes
    updateCoefficients();
    reset();
}

void ResonantFilter::setCutoff(float freqHz)
{
    // Clamp to valid range
    cutoff = std::clamp(freqHz, 20.0f, 20000.0f);
    smoothedCutoff.setTargetValue(cutoff);
}

void ResonantFilter::setResonance(float res)
{
    // Map 0-1 to Q 0.5-100
    resonance = std::clamp(res, 0.0f, 1.0f);

    // Q = 0.5 + 99.5 * res (exponential mapping would be more musical, but linear is fine)
    // Using exponential: Q = 0.5 * 200^res
    const float Q = 0.5f * std::pow(200.0f, resonance);

    // Auto-gain compensation: 1/sqrt(Q)
    autoGain = fastInvSqrt(Q);

    updateCoefficients();
}

void ResonantFilter::updateCoefficients()
{
    // TPT SVF coefficients
    // g = tan(π * fc / fs)
    // k = 2 - 2*g (for resonance damping)
    // Actually k = 2 - 2*g is for Chamberlin, Cytomic uses k = 1/Q

    // Get Q from resonance
    const float Q = 0.5f * std::pow(200.0f, resonance);

    // Compute g coefficient
    const float wc = Constants::PI * cutoff / static_cast<float>(sampleRate);
    g = std::tan(std::min(wc, Constants::HALF_PI * 0.99f));  // Clamp to avoid instability

    // Resonance damping coefficient (Cytomic style)
    k = 1.0f / Q;

    // Pre-compute frequently used values
    oneOverDenom = 1.0f / (1.0f + g * k + g * g);
}

void ResonantFilter::process(float* samples, int numSamples)
{
    // Check for modulation
    if (std::abs(modOctaves) > 0.001f)
    {
        // Modulated cutoff in octave space
        const float modCutoff = cutoff * std::pow(2.0f, modOctaves);
        const float clampedCutoff = std::clamp(modCutoff, 20.0f, 20000.0f);

        // Update coefficients for modulated cutoff
        const float wc = Constants::PI * clampedCutoff / static_cast<float>(sampleRate);
        g = std::tan(std::min(wc, Constants::HALF_PI * 0.99f));

        const float Q = 0.5f * std::pow(200.0f, resonance);
        k = 1.0f / Q;
        oneOverDenom = 1.0f / (1.0f + g * k + g * g);
    }

    // Process samples
    for (int i = 0; i < numSamples; ++i)
    {
        processSample(samples[i]);
    }
}

void ResonantFilter::processSample(float& sample)
{
    // TPT State Variable Filter (Cytomic topology)
    // v0 = input
    // v1 = (v0 - ic2eq - k*ic1eq) / (1 + k*g + g*g)
    // v2 = ic2eq + g*v1
    // v3 = ic1eq + g*v2
    // ic1eq = 2*v3 - 2*ic1eq
    // ic2eq = 2*v2 - 2*ic2eq

    const float v0 = sample * autoGain;  // Apply auto-gain compensation

    // Core calculation
    const float v1 = (v0 - ic2eq - k * ic1eq) * oneOverDenom;
    const float v2 = ic2eq + g * v1;
    const float v3 = ic1eq + g * v2;

    // Update state (before output calculation)
    ic1eq = 2.0f * v3 - 2.0f * ic1eq;
    ic2eq = 2.0f * v2 - 2.0f * ic2eq;

    // Output based on mode
    float output = 0.0f;

    switch (mode)
    {
        case Mode::LP:
            // Low-pass output
            output = v2;
            break;

        case Mode::HP:
            // High-pass output = v0 - k*v1 - v2
            output = v0 - k * v1 - v2;
            break;

        case Mode::BP:
            // Band-pass output
            output = v1;
            break;

        case Mode::Notch:
            // Notch output = v0 - k*v1 (HP + LP)
            output = v0 - k * v1;
            break;
    }

    sample = output;
}

void ResonantFilter::reset()
{
    ic1eq = 0.0f;
    ic2eq = 0.0f;
    smoothedCutoff.setCurrentAndTargetValue(cutoff);
}

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/DriveCircuit.h",
  "content": "#pragma once

#include <juce_core/juce_core.h>
#include <juce_audio_basics/juce_audio_basics.h>
#include "FastMath.h"
#include "DCBlocker.h"

namespace CogDSP
{

// DriveCircuit - Analog-style drive with adaptive pre-gain
// Stage 1: Adaptive pre-gain with RMS compression (10:1 above 0dBFS)
// Stage 2: Saturation core (warm/grit blend by drive amount)
// Stage 3: Tone tilt shelf at 1kHz (dark to bright)
// Bypass at drive=0 for transparency
class DriveCircuit
{
public:
    DriveCircuit() = default;
    ~DriveCircuit() = default;

    void prepare(double sampleRate, int samplesPerBlock);
    void process(float* left, float* right, int numSamples);
    void reset();

    // Drive: 0-1
    // 0 = bypass (transparent)
    // 0-0.5 = warm saturation
    // 0.5-1 = grit character
    void setDrive(float d) { drive = std::clamp(d, 0.0f, 1.0f); }

    // Tone: 0-1
    // 0 = -6dB highs (dark)
    // 0.5 = flat
    // 1 = +6dB highs (bright)
    void setTone(float t) { tone = std::clamp(t, 0.0f, 1.0f); }

private:
    // Stage 1: Adaptive pre-gain
    float computeAdaptivePreGain(float rms);

    // Stage 2: Saturation core
    float processSaturation(float input, float drive);

    // Stage 3: Tone tilt shelf
    void processToneTilt(float& sample);

    // RMS computation
    float computeRMS(float* left, float* right, int numSamples);

    float drive = 0.0f;
    float tone = 0.5f;
    double sampleRate = 44100.0;

    // RMS smoothing
    float rmsValue = 0.0f;
    float rmsCoeff = 0.0f;

    // Tone tilt filter state (first-order shelf at 1kHz)
    float tiltStateL = 0.0f;
    float tiltStateR = 0.0f;
    float tiltCoeffA = 0.0f;  // High shelf coefficient
    float tiltCoeffB = 0.0f;  // Low shelf coefficient

    // Smoothed values
    juce::SmoothedValue<float> smoothedDrive;
    juce::SmoothedValue<float> smoothedTone;

    // Denormal prevention
    static constexpr float denormalThreshold = 1e-15f;
};

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/DriveCircuit.cpp",
  "content": "#include "DriveCircuit.h"
#include <cmath>

namespace CogDSP
{

void DriveCircuit::prepare(double sr, int samplesPerBlock)
{
    sampleRate = sr;

    // RMS smoothing coefficient (~5ms window)
    rmsCoeff = static_cast<float>(std::exp(-1.0 / (0.005 * sampleRate)));

    // Initialize smoothed values
    smoothedDrive.reset(sampleRate);
    smoothedDrive.setCurrentAndTargetValue(drive);
    smoothedDrive.setRampLength(0.02);  // 20ms smoothing

    smoothedTone.reset(sampleRate);
    smoothedTone.setCurrentAndTargetValue(tone);
    smoothedTone.setRampLength(0.02);

    reset();
}

void DriveCircuit::process(float* left, float* right, int numSamples)
{
    // Update smoothed parameters
    smoothedDrive.setTargetValue(drive);
    smoothedTone.setTargetValue(tone);
    smoothedDrive.skip(numSamples);
    smoothedTone.skip(numSamples);

    const float currentDrive = smoothedDrive.getCurrentValue();
    const float currentTone = smoothedTone.getCurrentValue();

    // Check for bypass condition
    if (currentDrive < 0.001f)
    {
        // Bypass entirely - transparent passthrough
        return;
    }

    // Stage 1: Compute adaptive pre-gain based on input RMS
    const float rms = computeRMS(left, right, numSamples);
    const float preGain = computeAdaptivePreGain(rms);

    // Update tone tilt coefficients based on current tone
    // Tone 0: dark (-6dB highs), Tone 0.5: flat, Tone 1: bright (+6dB highs)
    const float shelfGain = (currentTone - 0.5f) * 12.0f;  // -6dB to +6dB
    const float shelfCoeff = std::pow(10.0f, shelfGain / 40.0f);  // Convert to coefficient

    // Tone tilt at 1kHz
    const float wc = 2.0f * Constants::PI * 1000.0f / static_cast<float>(sampleRate);
    const float g = std::tan(wc / 2.0f);
    tiltCoeffA = g;
    tiltCoeffB = 1.0f / (1.0f + g);

    // Process samples
    for (int i = 0; i < numSamples; ++i)
    {
        // Stage 1: Apply adaptive pre-gain
        float outL = left[i] * preGain;
        float outR = right[i] * preGain;

        // Stage 2: Saturation core
        outL = processSaturation(outL, currentDrive);
        outR = processSaturation(outR, currentDrive);

        // Stage 3: Tone tilt
        processToneTilt(outL);
        processToneTilt(outR);

        left[i] = outL;
        right[i] = outR;
    }
}

float DriveCircuit::computeAdaptivePreGain(float rms)
{
    // Pre-gain: 0 to +24dB based on drive parameter
    float preGainDB = drive * 24.0f;

    // Adaptive compression: reduce pre-gain if input is hot
    // 10:1 compression above 0dBFS input
    if (rms > 1.0f)
    {
        const float overshootDB = 20.0f * std::log10(rms);
        preGainDB -= overshootDB * 0.9f;  // ~10:1 ratio
    }

    // Never attenuate below -6dB
    preGainDB = std::max(preGainDB, -6.0f);

    // Convert to linear gain
    return std::pow(10.0f, preGainDB / 20.0f);
}

float DriveCircuit::processSaturation(float input, float currentDrive)
{
    // Blend between warm and grit characters based on drive
    // 0-0.5: warm saturation (tanh)
    // 0.5-1: grit character

    if (currentDrive <= 0.5f)
    {
        // Warm saturation: tanh(x * (1 + drive * 3))
        const float warmDrive = currentDrive * 2.0f;  // Scale 0-0.5 to 0-1
        const float gain = 1.0f + warmDrive * 3.0f;
        return fastTanh(input * gain);
    }
    else
    {
        // Grit: x / (1 + |x|) + 0.1 * sin(x * PI) * exp(-x * x)
        // Blend from warm to grit as drive goes from 0.5 to 1
        const float gritBlend = (currentDrive - 0.5f) * 2.0f;  // 0-1 over this range

        // Warm component
        const float warmOutput = fastTanh(input);

        // Grit component
        const float x = input;
        const float softClip = x / (1.0f + std::abs(x));
        const float sineFold = 0.1f * std::sin(x * Constants::PI) * fastExpNegSquare(x);
        const float gritOutput = softClip + sineFold;

        // Blend
        return lerp(warmOutput, gritOutput, gritBlend);
    }
}

void DriveCircuit::processToneTilt(float& sample)
{
    // First-order shelf filter around 1kHz
    // Tone 0: -6dB highs, Tone 1: +6dB highs

    const float currentTone = smoothedTone.getCurrentValue();

    if (std::abs(currentTone - 0.5f) < 0.001f)
    {
        // Flat response - no filtering
        return;
    }

    // High shelf implementation
    // When tone > 0.5: boost highs
    // When tone < 0.5: cut highs

    const float shelfGain = (currentTone - 0.5f) * 12.0f;  // -6 to +6 dB
    const float A = std::pow(10.0f, shelfGain / 40.0f);

    // First-order high shelf
    // y[n] = x[n] - state + A * state
    // This is simplified - using one-pole filter

    const float highPass = sample - tiltStateL;
    tiltStateL = highPass * 0.3f + tiltStateL * 0.7f;  // Lowpass the HP output

    // Mix: lows pass through, highs are boosted/cut
    const float output = sample + (A - 1.0f) * highPass;

    sample = output;

    // Denormal prevention
    if (std::abs(sample) < denormalThreshold)
        sample = 0.0f;
}

float DriveCircuit::computeRMS(float* left, float* right, int numSamples)
{
    // Compute RMS over the block, smoothed across blocks
    float sumSq = 0.0f;
    for (int i = 0; i < numSamples; ++i)
    {
        const float mono = (left[i] + right[i]) * 0.5f;
        sumSq += mono * mono;
    }

    const float blockRMS = std::sqrt(sumSq / numSamples);

    // Exponential smoothing
    rmsValue = rmsCoeff * rmsValue + (1.0f - rmsCoeff) * blockRMS;

    return rmsValue;
}

void DriveCircuit::reset()
{
    rmsValue = 0.0f;
    tiltStateL = 0.0f;
    tiltStateR = 0.0f;
    smoothedDrive.setCurrentAndTargetValue(drive);
    smoothedTone.setCurrentAndTargetValue(tone);
}

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/StereoWidener.h",
  "content": "#pragma once

#include <juce_core/juce_core.h>
#include <juce_audio_basics/juce_audio_basics.h>
#include "FastMath.h"

namespace CogDSP
{

// StereoWidener - Frequency-dependent M/S processing
// Linkwitz-Riley 2nd-order crossover at 250Hz
// Below 250Hz: mono sum to both channels (solid centered low end)
// Above 250Hz: M/S widening (side boost up to 3x)
class StereoWidener
{
public:
    StereoWidener() = default;
    ~StereoWidener() = default;

    void prepare(double sampleRate);
    void process(float* left, float* right, int numSamples);
    void reset();

    // Width: 0-1
    // 0 = transparent (no change)
    // 1 = side tripled (extreme width, up to +9.5dB on stereo material)
    void setWidth(float w) { width = std::clamp(w, 0.0f, 1.0f); }

private:
    // LR2 crossover stage (2x biquad for 4th order LR)
    struct CrossoverStage
    {
        // First-order HPF and LPF (cascade two for LR2)
        float x1L = 0.0f, x2L = 0.0f;
        float y1L = 0.0f, y2L = 0.0f;
        float x1R = 0.0f, x2R = 0.0f;
        float y1R = 0.0f, y2R = 0.0f;

        // Coefficients
        float b0 = 0.0f, b1 = 0.0f, b2 = 0.0f;
        float a1 = 0.0f, a2 = 0.0f;

        void processLP(float& left, float& right)
        {
            // Low-pass: Butterworth 2nd order
            const float inL = left;
            const float inR = right;

            left = b0 * inL + b1 * x1L + b2 * x2L - a1 * y1L - a2 * y2L;
            right = b0 * inR + b1 * x1R + b2 * x2R - a1 * y1R - a2 * y2R;

            x2L = x1L; x1L = inL;
            y2L = y1L; y1L = left;
            x2R = x1R; x1R = inR;
            y2R = y1R; y1R = right;
        }

        void processHP(float& left, float& right)
        {
            // High-pass: Butterworth 2nd order
            const float inL = left;
            const float inR = right;

            left = b0 * inL + b1 * x1L + b2 * x2L - a1 * y1L - a2 * y2L;
            right = b0 * inR + b1 * x1R + b2 * x2R - a1 * y1R - a2 * y2R;

            x2L = x1L; x1L = inL;
            y2L = y1L; y1L = left;
            x2R = x1R; x1R = inR;
            y2R = y1R; y1R = right;
        }

        void reset()
        {
            x1L = x2L = y1L = y2L = 0.0f;
            x1R = x2R = y1R = y2R = 0.0f;
        }
    };

    float width = 0.5f;
    double sampleRate = 44100.0;

    // Two LP stages for LR2 (cascade)
    CrossoverStage lp1, lp2;
    // Two HP stages for LR2 (cascade)
    CrossoverStage hp1, hp2;

    // Smoothed width
    juce::SmoothedValue<float> smoothedWidth;
};

} // namespace CogDSP"
}

{
  "file_path": "/home/myuser/CogVST/src/DSP/StereoWidener.cpp",
  "content": "#include "StereoWidener.h"
#include <cmath>

namespace CogDSP
{

void StereoWidener::prepare(double sr)
{
    sampleRate = sr;

    // Design LR2 crossover at 250Hz
    // LR2 = two Butterworth 2nd-order stages in cascade
    // Cutoff frequency for LR2: fc = 250Hz

    constexpr float crossoverFreq = 250.0f;

    // Butterworth 2nd-order coefficients
    // For LPF: wc = 2*PI*fc/fs
    // b0 = wc²/(1 + sqrt(2)*wc + wc²)
    // b1 = 2*b0
    // b2 = b0
    // a1 = 2*(wc² - 1)/(1 + sqrt(2)*wc + wc²)
    // a2 = (1 - sqrt(2)*wc + wc²)/(1 + sqrt(2)*wc + wc²)

    // For HPF: substitute wc → 1/wc (pre-wrapped)

    const float wc = Constants::PI * crossoverFreq / static_cast<float>(sampleRate);
    const float wc2 = wc * wc;
    const float sqrt2 = 1.41421356f;

    // LPF coefficients
    const float denom = 1.0f + sqrt2 * wc + wc2;
    lp1.b0 = wc2 / denom;
    lp1.b1 = 2.0f * lp1.b0;
    lp1.b2 = lp1.b0;
    lp1.a1 = 2.0f * (wc2 - 1.0f) / denom;
    lp1.a2 = (1.0f - sqrt2 * wc + wc2) / denom;

    // Copy for second stage
    lp2.b0 = lp1.b0;
    lp2.b1 = lp1.b1;
    lp2.b2 = lp1.b2;
    lp2.a1 = lp1.a1;
    lp2.a2 = lp1.a2;

    // HPF coefficients (pre-warped)
    // For HPF at same frequency: use the reciprocal transformation
    const float wcHP = wc;  // Already computed above
    const float wcHP2 = wcHP * wcHP;

    // High-pass Butterworth
    // b0 = 1 / denom
    // b1 = -2 / denom
    // b2 = 1 / denom
    // a1 = 2*(wc² - 1) / denom (same as LPF)
    // a2 = (1 - sqrt(2)*wc + wc²) / denom (same as LPF)

    const float denomHP = denom;  // Same denominator
    hp1.b0 = 1.0f / denomHP;
    hp1.b1 = -2.0f / denomHP;
    hp1.b2 = 1.0f / denomHP;
    hp1.a1 = lp1.a1;
    hp1.a2 = lp1.a2;

    // Copy for second stage
    hp2.b0 = hp1.b0;
    hp2.b1 = hp1.b1;
    hp2.b2 = hp1.b2;
    hp2.a1 = hp1.a1;
    hp2.a2 = hp1.a2;

    // Initialize smoothed width
    smoothedWidth.reset(sampleRate);
    smoothedWidth.setCurrentAndTargetValue(width);
    smoothedWidth.setRampLength(0.02);

    reset();
}

void StereoWidener::process(float* left, float* right, int numSamples)
{
    // Update smoothed width
    smoothedWidth.setTargetValue(width);
    smoothedWidth.skip(numSamples);
    const float currentWidth = smoothedWidth.getCurrentValue();

    // Check for bypass
    if (currentWidth < 0.001f)
    {
        // Transparent - no processing
        return;
    }

    for (int i = 0; i < numSamples; ++i)
    {
        float L = left[i];
        float R = right[i];

        // Split into low and high bands using LR2 crossover
        float lowL = L, lowR = R;
        float highL = L, highR = R;

        // LP path (two stages for LR2)
        lp1.processLP(lowL, lowR);
        lp2.processLP(lowL, lowR);

        // HP path (two stages for LR2)
        hp1.processHP(highL, highR);
        hp2.processHP(highL, highR);

        // Below 250Hz: mono sum to both channels
        const float lowMono = (lowL + lowR) * 0.5f;

        // Above 250Hz: M/S widening
        // Width = 0: no change (width * 2 + 1 = 1)
        // Width = 1: side tripled (width * 2 + 1 = 3)
        // mid = (L + R) / 2
        // side = (L - R) / 2
        // side *= (1 + width * 2)
        // L = mid + side, R = mid - side

        const float mid = (highL + highR) * 0.5f;
        const float side = (highL - highR) * 0.5f;
        const float widthMultiplier = 1.0f + currentWidth * 2.0f;
        const float widenedSide = side * widthMultiplier;

        const float highOutL = mid + widenedSide;
        const float highOutR = mid - widenedSide;

        // Recombine
        left[i] = lowMono + highOutL;
        right[i] = lowMono + highOutR;
    }
}

void StereoWidener::reset()
{
    lp1.reset();
    lp2.reset();
    hp1.reset();
    hp2.reset();
    smoothedWidth.setCurrentAndTargetValue(width);
}

} // namespace CogDSP"
}

