  "content": "#include <catch2/catch_test_macros.hpp>
#include <juce_audio_processors/juce_audio_processors.h>
#include "PluginProcessor.h"

// Test fixture for plugin instantiation
class PluginTest {
public:
    PluginTest() : processor(createPluginFilter()) {}
    ~PluginTest() { processor.reset(); }

protected:
    std::unique_ptr<juce::AudioProcessor> processor;
};

TEST_CASE("Plugin instantiates correctly", "[plugin]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    REQUIRE(processor != nullptr);
}

TEST_CASE("Plugin reports correct basic info", "[plugin]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());

    REQUIRE(processor->getName() == juce::String("Cog VST"));
    REQUIRE(processor->acceptsMidi() == false);
    REQUIRE(processor->producesMidi() == false);
    REQUIRE(processor->isMidiEffect() == false);
    REQUIRE(processor->getTailLengthSeconds() >= 0.0);
}

TEST_CASE("Plugin accepts stereo and mono input", "[plugin]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());

    // Stereo input/output
    juce::AudioProcessor::BusesLayout stereoLayout;
    stereoLayout.inputBuses = juce::AudioChannelSet::stereo();
    stereoLayout.outputBuses = juce::AudioChannelSet::stereo();
    REQUIRE(processor->isBusesLayoutSupported(stereoLayout) == true);

    // Mono input, stereo output
    juce::AudioProcessor::BusesLayout monoInputLayout;
    monoInputLayout.inputBuses = juce::AudioChannelSet::mono();
    monoInputLayout.outputBuses = juce::AudioChannelSet::stereo();
    REQUIRE(processor->isBusesLayoutSupported(monoInputLayout) == true);
}

TEST_CASE("Plugin prepares without error", "[plugin]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());

    REQUIRE_NOTHROW(processor->prepareToPlay(44100.0, 512));
    REQUIRE_NOTHROW(processor->prepareToPlay(48000.0, 256));
    REQUIRE_NOTHROW(processor->prepareToPlay(96000.0, 128));
    REQUIRE_NOTHROW(processor->prepareToPlay(192000.0, 64));
}

TEST_CASE("Plugin processes silence without crash", "[plugin][smoke]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    processor->prepareToPlay(48000.0, 512);

    juce::AudioBuffer<float> buffer(2, 512);
    buffer.clear();
    juce::MidiBuffer midiBuffer;

    REQUIRE_NOTHROW(processor->processBlock(buffer, midiBuffer));
}

TEST_CASE("Plugin processes noise without crash", "[plugin][smoke]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    processor->prepareToPlay(48000.0, 512);

    juce::AudioBuffer<float> buffer(2, 512);
    juce::MidiBuffer midiBuffer;

    // Fill with random noise
    for (int ch = 0; ch < 2; ++ch) {
        auto* channelData = buffer.getWritePointer(ch);
        for (int i = 0; i < 512; ++i) {
            channelData[i] = (juce::Random::getSystemRandom().nextFloat() * 2.0f) - 1.0f;
        }
    }

    REQUIRE_NOTHROW(processor->processBlock(buffer, midiBuffer));

    // Check output is finite (no NaN/Inf)
    for (int ch = 0; ch < 2; ++ch) {
        auto* channelData = buffer.getReadPointer(ch);
        for (int i = 0; i < 512; ++i) {
            REQUIRE(std::isfinite(channelData[i]));
        }
    }
}

TEST_CASE("Multi-instance test - no shared state corruption", "[plugin][stress]") {
    // Create multiple instances
    std::vector<std::unique_ptr<juce::AudioProcessor>> instances;

    for (int i = 0; i < 4; ++i) {
        auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
        processor->prepareToPlay(48000.0, 256);
        instances.push_back(std::move(processor));
    }

    // Process different audio through each
    juce::AudioBuffer<float> buffer(2, 256);
    juce::MidiBuffer midiBuffer;

    for (auto& processor : instances) {
        buffer.clear();
        for (int ch = 0; ch < 2; ++ch) {
            auto* channelData = buffer.getWritePointer(ch);
            for (int i = 0; i < 256; ++i) {
                channelData[i] = (juce::Random::getSystemRandom().nextFloat() * 2.0f) - 1.0f;
            }
        }

        REQUIRE_NOTHROW(processor->processBlock(buffer, midiBuffer));
    }

    // All instances should process independently without cross-talk
    REQUIRE(instances.size() == 4);
}"
}

