TEST_CASE("Feedback parameter is clamped to 0.95", "[parameters]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    auto* apvts = dynamic_cast<CogVSTAudioProcessor*>(processor.get())->getAPVTS();

    auto* param = apvts.getParameter("feedback");
    REQUIRE(param != nullptr);

    // Set to maximum (should be clamped to 0.95 internally)
    param->setValueNotifyingHost(1.0f);

