        }
    }
}

TEST_CASE("Sensitivity parameter range is 0-1", "[parameters]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    auto& apvts = dynamic_cast<CogVSTAudioProcessor*>(processor.get())->getAPVTS();

    auto* param = apvts.getParameter("sensitivity");
    REQUIRE(param != nullptr);

    // Check normalized range
    param->setValueNotifyingHost(0.0f);
    REQUIRE(param->getValue() == 0.0f);

    param->setValueNotifyingHost(1.0f);
    REQUIRE(param->getValue() == 1.0f);
}

TEST_CASE("Filter cutoff parameter range is valid", "[parameters]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    auto& apvts = dynamic_cast<CogVSTAudioProcessor*>(processor.get())->getAPVTS();

    auto* paramA = apvts.getParameter("filterACutoff");
    auto* paramB = apvts.getParameter("filterBCutoff");

    REQUIRE(paramA != nullptr);
    REQUIRE(paramB != nullptr);

    // Cutoff should map to 20Hz - 20kHz
    // The parameter is normalized 0-1, but internally should map to frequency range
    paramA->setValueNotifyingHost(0.0f);  // Should be ~20Hz
    paramA->setValueNotifyingHost(1.0f);  // Should be ~20kHz
}

TEST_CASE("Feedback parameter is clamped to 0.95", "[parameters]") {
    auto processor = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    auto& apvts = dynamic_cast<CogVSTAudioProcessor*>(processor.get())->getAPVTS();

    auto* param = apvts.getParameter("feedback");
    REQUIRE(param != nullptr);

    // Set to maximum (should be clamped to 0.95 internally)
    param->setValueNotifyingHost(1.0f);

    // Process audio - should not explode
    processor->prepareToPlay(48000.0, 512);
    juce::AudioBuffer<float> buffer(2, 512);
    buffer.clear();
    juce::MidiBuffer midiBuffer;

    for (int ch = 0; ch < 2; ++ch) {
        auto* channelData = buffer.getWritePointer(ch);
        for (int i = 0; i < 512; ++i) {
            channelData[i] = 0.5f;
        }
    }

    // Run for multiple blocks to let feedback build
    for (int i = 0; i < 10; ++i) {
        REQUIRE_NOTHROW(processor->processBlock(buffer, midiBuffer));
    }

    // Output should still be bounded
    for (int ch = 0; ch < 2; ++ch) {
        auto* channelData = buffer.getReadPointer(ch);
        for (int i = 0; i < 512; ++i) {
            REQUIRE(std::isfinite(channelData[i]));
            REQUIRE(std::abs(channelData[i]) < 10.0f);  // Should not explode
        }
    }
}

TEST_CASE("State save/restore round-trip", "[parameters][state]") {
    auto processor1 = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());
    auto processor2 = std::unique_ptr<juce::AudioProcessor>(createPluginFilter());

    processor1->prepareToPlay(48000.0, 256);
    processor2->prepareToPlay(48000.0, 256);

    auto& params1 = processor1->getParameters();
    auto& params2 = processor2->getParameters();

    // Set some random parameter values on processor1
    params1[0]->setValue(0.3f);
    params1[1]->setValue(0.7f);
    params1[2]->setValue(0.5f);

    // Save state
    juce::MemoryBlock state;
    processor1->getStateInformation(state);

    // Restore to processor2
    processor2->setStateInformation(state.getData(), static_cast<int>(state.getSize()));

    // Verify parameters match
    for (int i = 0; i < 3; ++i) {
        float val1 = params1[i]->getValue();
        float val2 = params2[i]->getValue();
        REQUIRE(std::abs(val1 - val2) < 0.001f);
    }
}"
}

