78	    params.push_back(std::make_unique<juce::AudioParameterFloat>("filterBCutoff", "Filter B Cutoff", 20.0f, 20000.0f, 2000.0f));
79	    params.push_back(std::make_unique<juce::AudioParameterFloat>("filterBReso", "Filter B Reso", 0.0f, 1.0f, 0.2f));
80	    params.push_back(std::make_unique<juce::AudioParameterChoice>("filterBType", "Filter B Type", juce::StringArray{"LP", "HP", "BP", "Notch"}, 0));
81	
82	    // Drive Circuit
83	    params.push_back(std::make_unique<juce::AudioParameterFloat>("drive", "Drive", 0.0f, 1.0f, 0.0f));
84	    params.push_back(std::make_unique<juce::AudioParameterFloat>("tone", "Tone", 0.0f, 1.0f, 0.5f));
85	
86	    // Feedback
87	    params.push_back(std::make_unique<juce::AudioParameterFloat>("feedback", "Feedback", 0.0f, 0.95f, 0.3f));
88	
89	    // Stereo Widener
90	    params.push_back(std::make_unique<juce::AudioParameterFloat>("width", "Width", 0.0f, 1.0f, 0.5f));
91	
92	    // Modulation
93	    params.push_back(std::make_unique<juce::AudioParameterFloat>("evolutionSpeed", "Evolution", 0.0f, 1.0f, 0.3f));
94	    params.push_back(std::make_unique<juce::AudioParameterFloat>("complexity", "Complexity", 0.0f, 1.0f, 0.2f));
95	    params.push_back(std::make_unique<juce::AudioParameterFloat>("reactivity", "Reactivity", 0.0f, 1.0f, 0.3f));
96	
97	    // Output
98	    params.push_back(std::make_unique<juce::AudioParameterFloat>("outputGain", "Output Gain", -12.0f, 12.0f, 0.0f));
99	    params.push_back(std::make_unique<juce::AudioParameterFloat>("mix", "Mix", 0.0f, 1.0f, 0.5f));
100	
101	    // Bypass / Freeze
102	    params.push_back(std::make_unique<juce::AudioParameterBool>("bypass", "Bypass", false));
103	    params.push_back(std::make_unique<juce::AudioParameterBool>("freeze", "Freeze", false));
104	
105	    // Preset Morphing
106	    params.push_back(std::make_unique<juce::AudioParameterFloat>("morph", "Morph", 0.0f, 1.0f, 0.0f));
107	    params.push_back(std::make_unique<juce::AudioParameterFloat>("morphTime", "Morph Time", 0.1f, 30.0f, 2.0f));
108	
109	    return { params.begin(), params.end() };
110	}
