112	//==============================================================================
113	void CogVSTAudioProcessor::prepareToPlay(double sampleRate, int samplesPerBlock)
114	{
115	    // Initialize DSP modules
116	    detector.prepare(sampleRate, samplesPerBlock);
117	
118	    // Spectral engine latency (2048 samples at 48kHz ≈ 42ms)
119	    spectralLatency = 2048 / 2;  // hop size
120	    spectralEngine.prepare(sampleRate, samplesPerBlock);
121	
122	    waveshaper.prepare(sampleRate, samplesPerBlock, spectralEngine.getLatencySamples());
123	    chorus.prepare(sampleRate, samplesPerBlock);
124	    filterA.prepare(sampleRate);
125	    filterB.prepare(sampleRate);
126	    driveCircuit.prepare(sampleRate, samplesPerBlock);
127	    widener.prepare(sampleRate);
128	    modulation.prepare(sampleRate, samplesPerBlock);
129	
130	    // Prepare delays
131	    const float maxDelayMs = 100.0f;  // Max feedback delay
132	    dryDelay.prepare(sampleRate, maxDelayMs);
133	    feedbackDelay.prepare(sampleRate, maxDelayMs);
134	
135	    // DC blockers for feedback
136	    feedbackDCBlockerL.prepare(sampleRate);
137	    feedbackDCBlockerR.prepare(sampleRate);
138	
139	    // Smoothed values
140	    smoothedPathBalance.reset(sampleRate, 0.002);  // 2ms
141	    smoothedPathBalance.setCurrentAndTargetValue(0.5f);
142	
143	    smoothedMix.reset(sampleRate, 0.02);  // 20ms
144	    smoothedMix.setCurrentAndTargetValue(0.5f);
145	
146	    smoothedOutputGain.reset(sampleRate, 0.02);
147	    smoothedOutputGain.setCurrentAndTargetValue(1.0f);
148	
149	    smoothedFeedback.reset(sampleRate, 0.02);
150	    smoothedFeedback.setCurrentAndTargetValue(0.0f);
151	
152	    // Feedback buffer
153	    feedbackBufferL.resize(samplesPerBlock * 2);
154	    feedbackBufferR.resize(samplesPerBlock * 2);
155	    std::fill(feedbackBufferL.begin(), feedbackBufferL.end(), 0.0f);
156	    std::fill(feedbackBufferR.begin(), feedbackBufferR.end(), 0.0f);
157	
158	    // Report latency to DAW
159	    setLatencySamples(spectralEngine.getLatencySamples());
160	
161	    // Reset bypass state
162	    bypassCrossfade = 1.0f;
163	    wasBypassed = false;
164	}
