182	//==============================================================================
183	void CogVSTAudioProcessor::processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages)
184	{
185	    juce::ignoreUnused(midiMessages);
186	    juce::ScopedNoDenormals noDenormals;
187	
188	    const int numSamples = buffer.getNumSamples();
189	    auto* left = buffer.getWritePointer(0);
190	    auto* right = buffer.getNumChannels() > 1 ? buffer.getWritePointer(1) : left;
191	
192	    // Get parameter values
193	    const float sensitivity = paramSensitivity->load();
194	    const float pathBalance = paramPathBalance->load();
195	    const float textureDrive = paramTextureDrive->load();
196	    const float droneDensity = paramDroneDensity->load();
197	    const float spectralDrift = paramSpectralDrift->load();
198	    const float thickness = paramThickness->load();
199	    const int filterRouting = static_cast<int>(paramFilterRouting->load());
200	    const float filterACutoff = paramFilterACutoff->load();
201	    const float filterAReso = paramFilterAReso->load();
202	    const int filterAType = static_cast<int>(paramFilterAType->load());
203	    const float filterBCutoff = paramFilterBCutoff->load();
204	    const float filterBReso = paramFilterBReso->load();
205	    const int filterBType = static_cast<int>(paramFilterBType->load());
206	    const float drive = paramDrive->load();
207	    const float tone = paramTone->load();
208	    const float feedback = paramFeedback->load();
209	    const float width = paramWidth->load();
210	    const float evolutionSpeed = paramEvolutionSpeed->load();
211	    const float complexity = paramComplexity->load();
212	    const float reactivity = paramReactivity->load();
213	    const float outputGain = paramOutputGain->load();
214	    const float mix = paramMix->load();
215	    const bool bypass = paramBypass->load() > 0.5f;
216	    const bool freeze = paramFreeze->load() > 0.5f;
217	
218	    // Bypass crossfade
219	    if (bypass && !wasBypassed)
220	    {
221	        // Entering bypass
222	        bypassCrossfade = 1.0f;
223	    }
224	    else if (!bypass && wasBypassed)
225	    {
226	        // Exiting bypass
227	        bypassCrossfade = 0.0f;
228	    }
229	    wasBypassed = bypass;
230	
231	    // Bypass crossfade rate (~5ms)
232	    const float crossfadeRate = 1.0f / (0.005f * static_cast<float>(getSampleRate()));
233	    if (bypass)
234	    {
235	        bypassCrossfade = std::max(0.0f, bypassCrossfade - crossfadeRate * numSamples);
236	    }
237	    else
238	    {
239	        bypassCrossfade = std::min(1.0f, bypassCrossfade + crossfadeRate * numSamples);
240	    }
241	
242	    // If fully bypassed, pass through
243	    if (bypass && bypassCrossfade < 0.001f)
244	    {
245	        return;  // Dry passthrough
246	    }
247	
248	    // Store dry signal for mixing
249	    std::vector<float> dryL(numSamples), dryR(numSamples);
250	    for (int i = 0; i < numSamples; ++i)
251	    {
252	        dryL[i] = left[i];
253	        dryR[i] = right[i];
254	    }
255	
256	    // Update modulation engine
257	    modulation.setEvolutionSpeed(evolutionSpeed);
258	    modulation.setComplexity(complexity);
259	    modulation.setReactivity(reactivity);
260	    modulation.process(numSamples);
261	
262	    // Update DSP parameters
263	    detector.setSensitivity(sensitivity);
264	    waveshaper.setDrive(textureDrive);
265	    spectralEngine.setDroneDensity(droneDensity);
266	    spectralEngine.setSpectralDrift(spectralDrift);
267	    spectralEngine.setFreeze(freeze);
268	    chorus.setThickness(thickness);
269	    filterA.setCutoff(filterACutoff);
270	    filterA.setResonance(filterAReso);
271	    filterA.setMode(static_cast<CogDSP::ResonantFilter::Mode>(filterAType));
272	    filterB.setCutoff(filterBCutoff);
273	    filterB.setResonance(filterBReso);
274	    filterB.setMode(static_cast<CogDSP::ResonantFilter::Mode>(filterBType));
275	    driveCircuit.setDrive(drive);
276	    driveCircuit.setTone(tone);
277	    widener.setWidth(width);
278	
279	    // Update smoothed values
280	    smoothedPathBalance.setTargetValue(pathBalance);
281	    smoothedMix.setTargetValue(mix);
282	    smoothedOutputGain.setTargetValue(std::pow(10.0f, outputGain / 20.0f));
283	    smoothedFeedback.setTargetValue(feedback);
284	
285	    // Skip samples for smoothed values
286	    smoothedPathBalance.skip(numSamples);
287	    smoothedMix.skip(numSamples);
288	    smoothedOutputGain.skip(numSamples);
289	    smoothedFeedback.skip(numSamples);
290	
291	    // Apply modulation to filters
292	    const float lfoA = modulation.getLFOAOutput();
293	    const float lfoB = modulation.getLFOBOutput();
294	    const float audioReactive = modulation.getAudioReactiveMod();
295	    const float spectralFluxMod = modulation.getSpectralFluxMod();
296	
297	    // Sum modulation in octave-space
298	    float filterAModOctaves = lfoA + audioReactive + spectralFluxMod * 0.5f;
299	    float filterBModOctaves = lfoB + audioReactive + spectralFluxMod * 0.5f;
300	    filterAModOctaves = std::clamp(filterAModOctaves, -4.0f, 4.0f);
301	    filterBModOctaves = std::clamp(filterBModOctaves, -4.0f, 4.0f);
302	
303	    filterA.setModulationOctaves(filterAModOctaves);
304	    filterB.setModulationOctaves(filterBModOctaves);
305	
306	    // Process detector
307	    detector.process(left, numSamples);
308	    const float pathAGain = detector.getPathAGain();
309	    const float pathBGain = detector.getPathBGain();
310	
311	    // Process signal chain
312	    // Path A: Texture/Waveshaper path
313	    std::vector<float> pathAOut(numSamples);
314	    for (int i = 0; i < numSamples; ++i)
315	    {
316	        pathAOut[i] = left[i] * pathAGain;
317	    }
318	    float* pathAOutPtr = pathAOut.data();
319	    waveshaper.process(pathAOutPtr, pathAOutPtr, numSamples);
320	
321	    // Path B: Spectral/Chorus path (mono processing)
322	    std::vector<float> pathBOutL(numSamples), pathBOutR(numSamples);
323	    spectralEngine.process(left, pathBOutL.data(), pathBOutR.data(), numSamples);
324	    chorus.process(pathBOutL.data(), pathBOutR.data(), numSamples);
325	
326	    // Multiply path B by path gain
327	    for (int i = 0; i < numSamples; ++i)
328	    {
329	        pathBOutL[i] *= pathBGain;
330	        pathBOutR[i] *= pathBGain;
331	    }
332	
333	    // Merge paths with equal-power crossfade
334	    const float balance = smoothedPathBalance.getCurrentValue();
335	    const auto crossfade = CogDSP::equalPowerCrossfade(balance);
336	    std::vector<float> mergeL(numSamples), mergeR(numSamples);
337	    for (int i = 0; i < numSamples; ++i)
338	    {
339	        // Path A to stereo (it's already stereo from waveshaper)
340	        mergeL[i] = pathAOut[i] * crossfade.dry + pathBOutL[i] * crossfade.wet;
341	        mergeR[i] = pathAOut[i] * crossfade.dry + pathBOutR[i] * crossfade.wet;
342	    }
343	
344	    // Add feedback
345	    const float fbAmount = smoothedFeedback.getCurrentValue();
346	    for (int i = 0; i < numSamples; ++i)
347	    {
348	        mergeL[i] += feedbackBufferL[i] * fbAmount;
349	        mergeR[i] += feedbackBufferR[i] * fbAmount;
350	    }
351	
352	    // Process filters
353	    if (filterRouting == 0)
354	    {
355	        // Parallel
356	        filterA.process(mergeL.data(), mergeR.data(), numSamples);
357	        filterB.process(mergeL.data(), mergeR.data(), numSamples);
358	    }
359	    else
360	    {
361	        // Series: A → B
362	        filterA.process(mergeL.data(), mergeR.data(), numSamples);
363	        filterB.process(mergeL.data(), mergeR.data(), numSamples);
364	    }
365	
366	    // Process drive circuit
367	    driveCircuit.process(mergeL.data(), mergeR.data(), numSamples);
368	
369	    // Feedback tap (after drive, before widener)
370	    for (int i = 0; i < numSamples; ++i)
371	    {
372	        feedbackBufferL[i] = feedbackDCBlockerL.processSample(mergeL[i]);
373	        feedbackBufferR[i] = feedbackDCBlockerR.processSample(mergeR[i]);
374	        // Soft clip feedback
375	        feedbackBufferL[i] = CogDSP::fastTanh(feedbackBufferL[i]);
376	        feedbackBufferR[i] = CogDSP::fastTanh(feedbackBufferR[i]);
377	    }
378	
379	    // Stereo widener
380	    widener.process(mergeL.data(), mergeR.data(), numSamples);
381	
382	    // Final limiter (tanh)
383	    for (int i = 0; i < numSamples; ++i)
384	    {
385	        mergeL[i] = CogDSP::fastTanh(mergeL[i]);
386	        mergeR[i] = CogDSP::fastTanh(mergeR[i]);
387	    }
388	
389	    // Output gain
390	    const float outGain = smoothedOutputGain.getCurrentValue();
391	    for (int i = 0; i < numSamples; ++i)
392	    {
393	        mergeL[i] *= outGain;
394	        mergeR[i] *= outGain;
395	    }
396	
397	    // Dry/wet mix with equal-power crossfade
398	    const auto mixGains = CogDSP::equalPowerCrossfade(smoothedMix.getCurrentValue());
399	    for (int i = 0; i < numSamples; ++i)
400	    {
401	        // Apply bypass crossfade
402	        const float wetL = mergeL[i] * bypassCrossfade;
403	        const float wetR = mergeR[i] * bypassCrossfade;
404	        const float drySignalL = dryL[i] * (1.0f - bypassCrossfade);
405	        const float drySignalR = dryR[i] * (1.0f - bypassCrossfade);
406	
407	        left[i] = drySignalL * mixGains.dry + wetL * mixGains.wet;
408	        right[i] = drySignalR * mixGains.dry + wetR * mixGains.wet;
409	    }
410	}
