8	
9	void SpectralDroneEngine::prepare(double sr, int samplesPerBlock)
10	{
11	    sampleRate = sr;
12	
13	    // Determine if we need resampling
14	    needsResampling = (sampleRate != internalRate);
15	    if (needsResampling)
16	    {
17	        resampleRatio = static_cast<int>(std::round(sampleRate / internalRate));
18	    }
19	    else
20	    {
21	        resampleRatio = 1;
22	    }
23	
24	    // Initialize FFT
25	    fft = std::make_unique<juce::dsp::FFT>(static_cast<int>(std::log2(fftSize)));
26	
27	    // Allocate buffers for 48kHz processing
28	    const int maxFrames = static_cast<int>(internalRate * 0.1);  // 100ms max at 48kHz
29	    inputBuffer48k.resize(fftSize * 4, 0.0f);
30	    outputBuffer48k.resize(fftSize * 4, 0.0f);
31	    overlapAddBuffer.resize(fftSize * 4, 0.0f);
32	
33	    // Pre-compute Hann window
34	    hannWindow.resize(fftSize);
35	    for (int i = 0; i < fftSize; ++i)
36	    {
37	        hannWindow[i] = 0.5f * (1.0f - std::cos(2.0f * Constants::PI * i / (fftSize - 1)));
38	    }
39	
40	    // Allocate spectral workspace
41	    fftWorkspace.resize(fftSize);
42	    prevFrame.resize(fftSize / 2 + 1, std::complex<float>(0.0f, 0.0f));
43	    frozenFrame.resize(fftSize / 2 + 1, std::complex<float>(0.0f, 0.0f));
44	
45	    // Filter state
46	    antiAliasState.resize(2, 0.0f);  // 2nd-order Butterworth
47	    antiImageState.resize(2, 0.0f);
48	
49	    // Initialize smoothed values
50	    smoothedDensity.reset(internalRate, 0.02);
51	    smoothedDensity.setCurrentAndTargetValue(droneDensity);
52	
53	    smoothedDrift.reset(internalRate, 0.02);
54	    smoothedDrift.setCurrentAndTargetValue(spectralDrift);
55	
56	    reset();
57	}
58	
59	void SpectralDroneEngine::process(const float* input, float* leftOut, float* rightOut, int numSamples)
60	{
61	    // Downsample to mono 48kHz
62	    downsampleToMono48k(input, numSamples);
63	
64	    // Process spectral engine
65	    processSpectral(numSamples);
66	
67	    // Upsample to stereo native rate
68	    upsampleToStereoNative(leftOut, rightOut, numSamples);
69	}
70	
71	void SpectralDroneEngine::downsampleToMono48k(const float* input, int numSamples)
72	{
73	    if (needsResampling)
74	    {
75	        // Downsample: sum stereo to mono, then decimate
76	        int outIndex = 0;
77	
78	        for (int i = 0; i < numSamples && outIndex < inputBuffer48k.size(); i += resampleRatio)
79	        {
80	            float mono = 0.0f;
81	            int count = 0;
82	
83	            // Average over resampleRatio samples
84	            for (int j = 0; j < resampleRatio && (i + j) < numSamples; ++j)
85	            {
86	                mono += input[i + j];
87	                ++count;
88	            }
89	
90	            mono /= static_cast<float>(count);
91	
92	            // Apply anti-alias filter
93	            applyAntiAliasFilter(&mono, 1);
94	
95	            // Write to input buffer
96	            inputBuffer48k[inputWritePos] = mono;
97	            inputWritePos = (inputWritePos + 1) % inputBuffer48k.size();
98	            ++outIndex;
99	        }
100	    }
101	    else
102	    {
103	        // No resampling needed - copy mono directly
104	        for (int i = 0; i < numSamples; ++i)
105	        {
106	            inputBuffer48k[inputWritePos] = input[i];
107	            inputWritePos = (inputWritePos + 1) % inputBuffer48k.size();
108	        }
109	    }
110	}
111	
112	void SpectralDroneEngine::processSpectral(int numSamples)
113	{
114	    // Update smoothed parameters
115	    smoothedDensity.setTargetValue(droneDensity);
116	    smoothedDrift.setTargetValue(spectralDrift);
117	
118	    // Process FFT frames on hop boundaries
119	    hopCounter += needsResampling ? (numSamples / resampleRatio) : numSamples;
120	
121	    if (hopCounter >= hopSize)
122	    {
123	        hopCounter = 0;
124	        computeFFTFrame();
125	    }
126	
127	    // Handle freeze crossfade
128	    if (frozen != wasFrozen)
129	    {
130	        freezeCrossfade = 0.0f;
131	        wasFrozen = frozen;
132	    }
133	
134	    if (freezeCrossfade < 1.0f)
135	    {
136	        freezeCrossfade += freezeCrossfadeRate;
137	        freezeCrossfade = std::min(freezeCrossfade, 1.0f);
138	    }
139	}
140	
141	void SpectralDroneEngine::computeFFTFrame()
142	{
143	    // Copy input with Hann window to workspace
144	    for (int i = 0; i < fftSize; ++i)
145	    {
146	        const int readPos = (inputWritePos - fftSize + i + inputBuffer48k.size()) % inputBuffer48k.size();
147	        fftWorkspace[i] = std::complex<float>(inputBuffer48k[readPos] * hannWindow[i], 0.0f);
148	    }
149	
150	    // Perform FFT
151	    fft->perform(fftWorkspace.data(), fftWorkspace.data(), false);
152	
153	    // Process spectral domain
154	    processSpectralFrame(fftWorkspace.data());
155	
156	    // Perform inverse FFT
157	    fft->perform(fftWorkspace.data(), fftWorkspace.data(), true);
158	
159	    // Overlap-add to output buffer
160	    for (int i = 0; i < fftSize; ++i)
161	    {
162	        const int writePos = (outputReadPos + i) % overlapAddBuffer.size();
163	        overlapAddBuffer[writePos] += fftWorkspace[i].real() * hannWindow[i];
164	    }
165	}
166	
167	void SpectralDroneEngine::processSpectralFrame(std::complex<float>* frame)
168	{
169	    const float density = smoothedDensity.getCurrentValue();
170	    const float drift = smoothedDrift.getCurrentValue();
171	    const int numBins = fftSize / 2 + 1;
172	
173	    // Apply spectral freeze/smear and drift
174	    for (int bin = 0; bin < numBins; ++bin)
175	    {
176	        std::complex<float> currentBin = frame[bin];
177	
178	        if (frozen)
179	        {
180	            // Freeze: hold previous content, allow drift to modulate it
181	            if (freezeCrossfade < 1.0f)
182	            {
183	                // Crossfade from live to frozen
184	                currentBin = currentBin * (1.0f - freezeCrossfade) + frozenFrame[bin] * freezeCrossfade;
185	            }
186	            else
187	            {
188	                currentBin = frozenFrame[bin];
189	            }
190	        }
191	        else
192	        {
193	            // Normal operation: blend current with previous
194	            if (freezeCrossfade < 1.0f)
195	            {
196	                // Crossfade from frozen to live
197	                currentBin = currentBin * freezeCrossfade + frozenFrame[bin] * (1.0f - freezeCrossfade);
198	            }
199	
200	            // Spectral blend (smear/freeze amount)
201	            // blendCoeff = density (0-1), or 1.0 when frozen
202	            frame[bin] = currentBin * (1.0f - density) + prevFrame[bin] * density;
203	        }
204	
205	        // Spectral drift: rotate bins
206	        if (std::abs(drift) > 0.001f)
207	        {
208	            const float driftAmount = drift * 0.5f;  // Scale drift sensitivity
209	
210	            // Simple bin rotation with phase modulation
211	            float phaseShift = driftAmount * bin * 0.01f;
212	            float re = frame[bin].real();
213	            float im = frame[bin].imag();
214	
215	            // Rotate phase
216	            frame[bin] = std::complex<float>(
217	                re * std::cos(phaseShift) - im * std::sin(phaseShift),
218	                re * std::sin(phaseShift) + im * std::cos(phaseShift)
219	            );
220	        }
221	
222	        // Store for next frame
223	        prevFrame[bin] = frame[bin];
224	
225	        if (frozen && freezeCrossfade >= 1.0f)
226	        {
227	            frozenFrame[bin] = frame[bin];
228	        }
229	    }
230	}
231	
232	void SpectralDroneEngine::upsampleToStereoNative(float* leftOut, float* rightOut, int numSamples)
233	{
234	    // Read from overlap-add buffer and output to both channels
235	    for (int i = 0; i < numSamples; ++i)
236	    {
237	        float sample = overlapAddBuffer[outputReadPos];
238	
239	        // Apply anti-image filter if upsampling
240	        if (needsResampling)
241	        {
242	            applyAntiImageFilter(&sample, 1);
243	
244	            // Zero-stuff and interpolate
245	            // For each output sample, interpolate between spectral samples
246	            const float frac = static_cast<float>(i % resampleRatio) / static_cast<float>(resampleRatio);
247	            const int pos0 = outputReadPos;
248	            const int pos1 = (outputReadPos + 1) % overlapAddBuffer.size();
249	
250	            sample = lerp(overlapAddBuffer[pos0], overlapAddBuffer[pos1], frac);
251	
252	            // Increment read position after each resample ratio samples
253	            if ((i + 1) % resampleRatio == 0)
254	            {
255	                outputReadPos = (outputReadPos + 1) % overlapAddBuffer.size();
256	            }
257	        }
258	        else
259	        {
260	            outputReadPos = (outputReadPos + 1) % overlapAddBuffer.size();
261	        }
262	
263	        // Output to both channels (mono -> stereo)
264	        leftOut[i] = sample;
265	        rightOut[i] = sample;
266	
267	        // Clear overlap-add buffer after reading
268	        overlapAddBuffer[outputReadPos] = 0.0f;
269	    }
270	}
271	
272	void SpectralDroneEngine::applyAntiAliasFilter(float* samples, int numSamples)
273	{
274	    // 2nd-order Butterworth lowpass at 20kHz
275	    // Coefficients for 48kHz sample rate
276	    constexpr float wc = 2.0f * Constants::PI * 20000.0f / 48000.0f;
277	    constexpr float c = 1.0f / std::tan(wc / 2.0f);
278	    constexpr float b0 = 1.0f / (1.0f + c * 1.41421356f + c * c);
279	    constexpr float b1 = 2.0f * b0;
280	    constexpr float b2 = b0;
281	    constexpr float a1 = 2.0f * (1.0f - c * c) * b0;
282	    constexpr float a2 = (1.0f - c * 1.41421356f + c * c) * b0;
283	
284	    for (int i = 0; i < numSamples; ++i)
285	    {
286	        const float input = samples[i];
287	        const float output = b0 * input + b1 * antiAliasState[0] + b2 * antiAliasState[1]
288	                           - a1 * antiAliasState[0] - a2 * antiAliasState[1];
289	
290	        antiAliasState[1] = antiAliasState[0];
291	        antiAliasState[0] = input;
292	        samples[i] = output;
293	    }
294	}
295	
296	void SpectralDroneEngine::applyAntiImageFilter(float* samples, int numSamples)
297	{
298	    // Same as anti-alias filter - 2nd-order Butterworth lowpass at 20kHz
299	    constexpr float wc = 2.0f * Constants::PI * 20000.0f / 48000.0f;
300	    constexpr float c = 1.0f / std::tan(wc / 2.0f);
301	    constexpr float b0 = 1.0f / (1.0f + c * 1.41421356f + c * c);
302	    constexpr float b1 = 2.0f * b0;
303	    constexpr float b2 = b0;
304	    constexpr float a1 = 2.0f * (1.0f - c * c) * b0;
305	    constexpr float a2 = (1.0f - c * 1.41421356f + c * c) * b0;
306	
307	    for (int i = 0; i < numSamples; ++i)
308	    {
309	        const float input = samples[i];
310	        const float output = b0 * input + b1 * antiImageState[0] + b2 * antiImageState[1]
311	                           - a1 * antiImageState[0] - a2 * antiImageState[1];
312	
313	        antiImageState[1] = antiImageState[0];
314	        antiImageState[0] = input;
315	        samples[i] = output;
316	    }
317	}
