319	void SpectralDroneEngine::reset()
320	{
321	    std::fill(inputBuffer48k.begin(), inputBuffer48k.end(), 0.0f);
322	    std::fill(outputBuffer48k.begin(), outputBuffer48k.end(), 0.0f);
323	    std::fill(overlapAddBuffer.begin(), overlapAddBuffer.end(), 0.0f);
324	    std::fill(prevFrame.begin(), prevFrame.end(), std::complex<float>(0.0f, 0.0f));
325	    std::fill(frozenFrame.begin(), frozenFrame.end(), std::complex<float>(0.0f, 0.0f));
326	    std::fill(fftWorkspace.begin(), fftWorkspace.end(), std::complex<float>(0.0f, 0.0f));
327	
328	    inputWritePos = 0;
329	    outputReadPos = 0;
330	    hopCounter = 0;
331	    frozen = false;
332	    wasFrozen = false;
333	    freezeCrossfade = 1.0f;
334	
335	    smoothedDensity.setCurrentAndTargetValue(droneDensity);
336	    smoothedDrift.setCurrentAndTargetValue(spectralDrift);
337	}
