    sampleRate = sr;

    // Determine if we need resampling - only for integer multiples of 48kHz
    // For other rates (44.1kHz, 88.2kHz), process at native rate
    const double ratio = sampleRate / internalRate;

    if (ratio > 1.0 && std::abs(ratio - std::round(ratio)) < 0.01)
    {
        // Integer upsampling needed (e.g., 96kHz, 192kHz)
        needsResampling = true;
        resampleRatio = static_cast<int>(std::round(ratio));
