  "new_string": "void SpectralDroneEngine::upsampleToStereoNative(float* leftOut, float* rightOut, int numSamples)
{
    if (needsResampling && resampleRatio > 1)
    {
        // Upsampling: each spectral sample becomes resampleRatio output samples
        for (int i = 0; i < numSamples; ++i)
        {
            // Linear interpolation between samples
            const float phase = static_cast<float>(i % resampleRatio) / static_cast<float>(resampleRatio);
            const int basePos = outputReadPos;
            const int nextPos = (outputReadPos + 1) % overlapAddBuffer.size();

            const float sample = lerp(overlapAddBuffer[basePos], overlapAddBuffer[nextPos], phase);

            leftOut[i] = sample;
            rightOut[i] = sample;

            // Move to next spectral sample after resampleRatio outputs
            if ((i + 1) % resampleRatio == 0)
            {
                overlapAddBuffer[outputReadPos] = 0.0f;  // Clear after reading
                outputReadPos = (outputReadPos + 1) % overlapAddBuffer.size();
            }
        }
    }
    else
    {
        // No resampling - direct output
        for (int i = 0; i < numSamples; ++i)
        {
            const float sample = overlapAddBuffer[outputReadPos];
            leftOut[i] = sample;
            rightOut[i] = sample;

            overlapAddBuffer[outputReadPos] = 0.0f;  // Clear after reading
