public:
    explicit CogVSTAudioProcessorEditor(CogVSTAudioProcessor& p);
    ~CogVSTAudioProcessorEditor() override;

    void paint(juce::Graphics& g) override;
    void resized() override;

private:
    CogVSTAudioProcessor& audioProcessor;

    // Main control sliders
    juce::Slider sensitivitySlider;
    juce::Slider pathBalanceSlider;
    juce::Slider textureDriveSlider;
    juce::Slider droneDensitySlider;
    juce::Slider spectralDriftSlider;
    juce::Slider thicknessSlider;
    juce::Slider driveSlider;
    juce::Slider toneSlider;
    juce::Slider feedbackSlider;
