    // Bypass and freeze buttons
    juce::ToggleButton bypassButton;
    juce::ToggleButton freezeButton;

    // Slider attachments
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> sensitivityAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> pathBalanceAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> textureDriveAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> droneDensityAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> spectralDriftAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> thicknessAttachment;
