    std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> bypassAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> freezeAttachment;

    // Labels
    juce::Label sensitivityLabel;
    juce::Label pathBalanceLabel;
    juce::Label textureDriveLabel;
    juce::Label droneDensityLabel;
    juce::Label spectralDriftLabel;
    juce::Label thicknessLabel;
    juce::Label driveLabel;
    juce::Label toneLabel;
    juce::Label feedbackLabel;
    juce::Label widthLabel;
    juce::Label evolutionLabel;
    juce::Label outputGainLabel;
    juce::Label mixLabel;

    // Helper function to set up a slider with label
